/**
 * The guard in front of `create database` / `drop database`, and the URL
 * rewrite that puts a run in its own database.
 *
 * Both were shipped untested while their Rust twin
 * (`benchtools/src/bin/durust-benchmark-workload.rs`) had tests for each. That
 * is the wrong way round: `drop database` is the only unrecoverable statement
 * this repository issues, and the property that makes it safe — that a name
 * reaching it was generated by `postgresBenchmarkDatabase` — was pinned by
 * nothing. These cases are ported from that file so the two halves cannot
 * drift.
 */
import { describe, expect, it } from "vitest";
import {
  listStaleBenchmarkDatabases,
  partitionStaleBenchmarkDatabases,
  postgresBenchmarkDatabase,
  postgresUrlWithDatabase,
  sweepBenchmarkDatabases
} from "@durust/benchmark";
import { assertPostgresAvailableWhenRequired, postgresUrlFromEnv } from "@durust/testing";
import { Client } from "pg";

const postgresUrl = postgresUrlFromEnv();
assertPostgresAvailableWhenRequired(postgresUrl, "the benchmark database-guard suite");
const describePostgres = postgresUrl === undefined ? describe.skip : describe;

const NEWLINE = String.fromCharCode(10);

describe("benchmark database name guard", () => {
  it("refuses every name it cannot prove it generated", () => {
    const generated = postgresBenchmarkDatabase();
    // Every one of these can reach the sweep: the listing's `like` is a
    // filter, not a proof of origin.
    const refusedNames = [
      "durust_tsbench_UPPER",
      "durust_tsbench_",
      "durust_tsbench_1; drop database durust",
      "durust_tsbench_wgw-hyphen",
      "not_durust_tsbench_1",
      `durust_tsbench_${"x".repeat(64)}`,
      // Case-folding lookalikes. These matter because the statements used to
      // interpolate unquoted, where the server folds identifiers to lowercase.
      "durust_tsbench_ı", // Turkish dotless i
      "durust_tsbench_K", // KELVIN SIGN, lowercases to `k`
      "durust_tsbench_ｄ", // fullwidth d
      `durust_tsbench_1${NEWLINE}`,
      `${NEWLINE}durust_tsbench_1`,
      "durust_tsbench_1 ",
      'durust_tsbench_1"; drop database durust; --',
      "durust_tsbench_1--comment"
    ];
    const { droppable, refused } = partitionStaleBenchmarkDatabases([generated, ...refusedNames]);
    expect(
      droppable,
      `only the generated name may be dropped, got ${JSON.stringify(droppable)}`
    ).toEqual([generated]);
    expect(refused.map((entry) => entry.name)).toEqual(refusedNames);
    for (const { name, reason } of refused) {
      expect(reason, `\`${name}\` must be refused by name`).toContain(
        "refusing to create or drop database"
      );
    }
  });

  it("accepts exactly 63 bytes and refuses 64", () => {
    const prefix = "durust_tsbench_";
    const at63 = prefix + "9".repeat(63 - prefix.length);
    const at64 = prefix + "9".repeat(64 - prefix.length);
    expect(at63).toHaveLength(63);
    expect(at64).toHaveLength(64);
    const { droppable, refused } = partitionStaleBenchmarkDatabases([at63, at64]);
    expect(droppable).toEqual([at63]);
    expect(refused.map((entry) => entry.name)).toEqual([at64]);
  });

  it("generates names it accepts", () => {
    const names = Array.from({ length: 8 }, () => postgresBenchmarkDatabase());
    expect(new Set(names).size, "generated names must be unique within a process").toBe(
      names.length
    );
    expect(partitionStaleBenchmarkDatabases(names).refused).toEqual([]);
  });
});

describe("benchmark database url rewrite", () => {
  it("keeps scheme, credentials, host, port and query", () => {
    const cases: readonly (readonly [string, string])[] = [
      [
        "postgres://postgres:postgres@localhost:5433/durust",
        "postgres://postgres:postgres@localhost:5433/durust_tsbench_1_2_3"
      ],
      [
        "postgres://user:pw@db.example:5432/durable?sslmode=require&connect_timeout=5",
        "postgres://user:pw@db.example:5432/durust_tsbench_1_2_3?sslmode=require&connect_timeout=5"
      ],
      // No path at all.
      ["postgres://localhost", "postgres://localhost/durust_tsbench_1_2_3"],
      // No path, but a query.
      [
        "postgres://localhost?sslmode=disable",
        "postgres://localhost/durust_tsbench_1_2_3?sslmode=disable"
      ],
      // Trailing slash, empty database.
      ["postgres://localhost/", "postgres://localhost/durust_tsbench_1_2_3"],
      // IPv6 literal: the authority contains colons, which must not split it.
      [
        "postgres://user@[2001:db8::1]:5432/durable",
        "postgres://user@[2001:db8::1]:5432/durust_tsbench_1_2_3"
      ],
      // A percent-encoded password containing what would otherwise be
      // delimiters. The URL syntax requires the encoding; unescaped it would
      // split in the wrong place, which is recorded on the function.
      [
        "postgresql://user:p%40ss%2Fword%3F%23@host:5432/durable",
        "postgresql://user:p%40ss%2Fword%3F%23@host:5432/durust_tsbench_1_2_3"
      ],
      // A fragment is preserved with the query tail.
      ["postgres://localhost/durable#frag", "postgres://localhost/durust_tsbench_1_2_3#frag"]
    ];
    for (const [input, expected] of cases) {
      expect(postgresUrlWithDatabase(input, "durust_tsbench_1_2_3"), input).toBe(expected);
    }
  });

  it("refuses a connection string that is not a URL", () => {
    // A unix-socket directory, a keyword/value DSN, and empty. `pg` accepts
    // the first two elsewhere, but neither has an authority to rewrite.
    // Failing here is what keeps a malformed value from reaching
    // `create database` — it is validated before the database exists.
    for (const input of ["/var/run/postgresql", "host=localhost dbname=durable", ""]) {
      expect(() => postgresUrlWithDatabase(input, "durust_tsbench_1_2_3"), input).toThrow(
        "must be a `postgres://"
      );
    }
  });
});

describePostgres("benchmark database sweep", () => {
  it("drops a generated database and spares a lookalike", async () => {
    const url = postgresUrl as string;
    const generated = postgresBenchmarkDatabase();
    const lookalike = "durust_tsbench_NotGenerated";
    await withAdmin(url, async (client) => {
      await client.query(`create database "${generated}"`);
      await client.query(`create database "${lookalike}"`);
    });
    try {
      // Scoped to this test's own candidates, never the server-wide listing.
      // A sweep over whatever the server happens to be holding would reclaim
      // databases belonging to work running concurrently — which is why the
      // listing and the decision are separate functions.
      await sweepBenchmarkDatabases(url, [generated, lookalike], true);
      const surviving = await withAdmin(url, async (client) => {
        const rows = await client.query(
          "select datname from pg_database where datname = any($1::text[]) order by datname",
          [[generated, lookalike]]
        );
        return rows.rows.map((row) => String((row as { readonly datname: unknown }).datname));
      });
      expect(
        surviving,
        "the generated name must be dropped and the unprovable lookalike left alone"
      ).toEqual([lookalike]);
    } finally {
      await withAdmin(url, async (client) => {
        await client.query(`drop database if exists "${lookalike}"`);
        await client.query(`drop database if exists "${generated}"`);
      });
    }
  });

  it("never lists a database with a live backend as stale", async () => {
    const url = postgresUrl as string;
    const generated = postgresBenchmarkDatabase();
    await withAdmin(url, async (client) => {
      await client.query(`create database "${generated}"`);
    });
    try {
      const attached = new Client({ connectionString: postgresUrlWithDatabase(url, generated) });
      await attached.connect();
      try {
        expect(
          await listStaleBenchmarkDatabases(url),
          `\`${generated}\` has a live backend and must not be listed as stale. A name says who ` +
            "created a database; only the server says whether it is in use"
        ).not.toContain(generated);
      } finally {
        await attached.end();
      }
      // And it becomes reclaimable once nothing is attached.
      await expect(listStaleBenchmarkDatabases(url)).resolves.toContain(generated);
    } finally {
      await withAdmin(url, async (client) => {
        await client.query(`drop database if exists "${generated}"`);
      });
    }
  });
});

async function withAdmin<T>(url: string, fn: (client: Client) => Promise<T>): Promise<T> {
  const client = new Client({ connectionString: url });
  await client.connect();
  try {
    return await fn(client);
  } finally {
    await client.end();
  }
}
